tools.post_process_code:
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict) and isinstance(d.get('products'), list):
            for p in d['products']:
                if not isinstance(p, dict):
                    continue
                t = p.get('type')
                if t == 'car_loan':
                    p['handling'] = 'No promise, no floor, no note. Transfer to queue restructuring.'
                    continue
                c = int(round(float(p.get('past_due') or 0) * 100))
                pct = 40 if t == 'credit_card' else 25
                p['floor'] = round(((c * pct + 50) // 100) / 100.0, 2)
                if int(p.get('days_late') or 0) <= 10:
                    p['band'] = 'early'
                    p['deadline'] = '2026-10-20 (Tuesday 20 October 2026)'
                    p['attempts'] = 1
                else:
                    p['band'] = 'late'
                    p['deadline'] = '2026-10-19 (Monday 19 October 2026)'
                    p['attempts'] = 2
            d['what_to_do_next'] = 'State every product in this order with its past_due, then ask once whether they can pay the full past_due of all non-car products today.'
        elif isinstance(d, dict):
            d['what_to_do_next'] = 'The account could not be loaded. Call get_account once more.'
except Exception:
    pass

try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            if str(d.get('ok')).lower() == 'true':
                d['what_to_do_next'] = 'Saved. Say exactly: A confirmation email will be sent to the address on file. Then go on with the next step.'
            else:
                d['what_to_do_next'] = 'Not saved. Call create_promise once more with the same values. If it fails again, say this promise could not be recorded.'
except Exception:
    pass

try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            d['what_to_do_next'] = 'Done. Go on with the next step.' if str(d.get('ok')).lower() == 'true' else 'Not done. Call add_note once more with the same values.'
except Exception:
    pass

try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            d['what_to_do_next'] = 'Transferred. Say a colleague will take over, then say goodbye ending with: Have a good day.' if str(d.get('ok')).lower() == 'true' else 'Not transferred. Call transfer_to_agent once more with the same queue.'
except Exception:
    pass

try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            d['what_to_do_next'] = 'Booked. Confirm the day and time to the customer.' if str(d.get('ok')).lower() == 'true' else 'Not booked. Call schedule_callback once more with the same values.'
except Exception:
    pass

try:
    def t(v):
        return str(v).lower() == 'true'
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            if t(d.get('all_verified')):
                n = 'Both answers are verified.'
            elif t(d.get('verified')):
                n = 'This answer is correct. Ask for the last four digits of the phone number.'
            elif str(d.get('wrong_answers_left')) == '0':
                n = 'Three wrong answers. Say you cannot continue without verification, do not mention the account, and end with: Have a good day.'
            elif not t(d.get('ok')):
                n = 'The answer could not be read and was not counted. Ask the customer to say it again.'
            else:
                n = 'Wrong answer. Ask the same question once more. Do not say what was wrong.'
            if d.get('hint') == 'day_month_swapped':
                n += ' The day and month may be swapped: read the date back to the customer and, if they confirm, call again with day and month the right way round.'
            d['what_to_do_next'] = n
except Exception:
    pass

